---@class FixQueue
local FixQueue = Class("FixQueue")

function FixQueue:__init(...)
    self.capacity = table.unpack(..., 1)
    self.queue = {}
    self.size_ = 0
    self.head = -1
    self.rear = -1
    self.onExtrudedAction = nil
end

function FixQueue:__delete()
    self.queue = nil
    self.size_ = 0
    self.head = -1
    self.rear = -1
    self.onExtrudedAction = nil
end

---EnQueue
---添加元素
---@param element table
function FixQueue:EnQueue(element)
    if self.size_ == 0 then
        self.head = 0
        self.rear = 1
        self.size_ = 1
        self.queue[self.rear] = element
    else
        local temp = (self.rear + 1) % self.capacity
        if temp == self.head then
            local item = self:DeQueue()
            if self.onExtrudedAction then
                self.onExtrudedAction(item)
            end
        else
            self.rear = temp
        end

        self.queue[self.rear] = element
        self.size_ = self.size_ + 1
    end

end

---DeQueue
function FixQueue:DeQueue()
    if self:IsEmpty() then
        printError("Error: The Queue is empty.")
        return
    end
    self.size_ = self.size_ - 1
    self.head = (self.head + 1) % self.capacity
    local value = self.queue[self.head]
    return value
end

function FixQueue:Remove(item)
    if not self:IsEmpty() then
        local t = {}
        for i = self.head, self.rear do
            if self.queue[i] ~= item then
                table.insert(t, self.queue[i])
            end
        end
        self:Clear()
        for i, v in pairs(t) do
            self:EnQueue(v)
        end
    end
end

function FixQueue:HasValue(item)
    local ret = false
    if not self:IsEmpty() then
        local t = {}
        for i = self.head, self.rear do
            if self.queue[i] == item then
                ret = true
                break
            end
        end
    end
    return ret
end

function FixQueue:HasId(identifier)
    local ret = false
    if not self:IsEmpty() then
        local t = {}
        for i = self.head, self.rear do
            if self.queue[i].identifier == identifier then
                ret = true
                break
            end
        end
    end
    return ret
end

function FixQueue:Clear()
    self.queue = nil
    self.queue = {}
    self.size_ = 0
    self.head = -1
    self.rear = -1
end

function FixQueue:IsEmpty()
    if self:Size() == 0 then
        return true
    end
    return false
end

function FixQueue:Size()
    return self.size_
end

function FixQueue:ToString()
    local h = self.head
    local r = self.rear
    local str = nil
    local first_flag = true
    while h ~= r do
        if first_flag == true then
            str = "{" .. self.queue[h]
            h = (h + 1) % self.capacity
            first_flag = false
        else
            str = str .. "," .. self.queue[h]
            h = (h + 1) % self.capacity
        end
    end
    str = str .. "," .. self.queue[r] .. "}"
    print(str)
end

