---UnloadCacheScene
---卸载缓存中的场景
---@param sceneInstance SceneInstance
function SceneManagement:UnloadCacheScene(sceneInstance)
    if self._currentScene == sceneInstance then
        self._cacheScenes:EnQueue(sceneInstance)
    else
        if not string.isEmpty(sceneInstance.identifier) then
            self._loadedScenes[tostring(sceneInstance.identifier)] = nil
        end
        ---真正的卸载场景的逻辑
        self:UnloadScene(sceneInstance)
    end
end

---UnloadScene
---@param sceneInstance SceneInstance
function SceneManagement:UnloadScene(sceneInstance)
    if isNull(sceneInstance) then
        return
    end
    if string.isEmpty(sceneInstance.identifier) then
        return
    end
    local identifier = sceneInstance.identifier
    local co = self._unloadingScenes[identifier]
    if isNull(co) then
        self._unloadingScenes[identifier] = identifier
        cs_coroutine.yield_return(self:__UnloadSceneCore(sceneInstance))
    end
    cs_coroutine.yield_return()
end

---__UnloadSceneCore
---@param sceneInstance SceneInstance
function SceneManagement:__UnloadSceneCore(sceneInstance)
    ---@type UnityEngine.SceneManagement.Scene
    local unityScene = sceneInstance:GetScene()
    if isNull(unityScene) then
        return
    end
    if not unityScene.isLoaded then
        return
    end

    ---sceneUnloaded
    ---@param s UnityEngine.SceneManagement.Scene
    local function sceneUnloaded(s)
        if s:IsValid() then
            if not string.isEmpty(sceneInstance.identifier) then
                local identifier = sceneInstance.identifier
                self._loadedScenes[identifier] = nil
                self._unloadingScenes[identifier] = nil
            end
            self._cacheScenes:Remove(sceneInstance)
            if self.onUnloadScene then
                self.onUnloadScene(sceneInstance)
            end
        end
    end

    SceneManager.sceneUnloaded('+', sceneUnloaded)
    cs_coroutine.yield_return(sceneInstance:UnloadScene())
    SceneManager.sceneUnloaded('-', sceneUnloaded)
    if self.onUnloadSceneComplete then
        self.onUnloadSceneComplete(sceneInstance)
    end
end

