---@param registerHistory boolean
function SceneManagement:Transition(argument, registerHistory)
    if isNull(registerHistory) then
        registerHistory = true
    end
    registerHistory = checkBool(registerHistory)
    if self:IsTransition() then
        return
    end
    if string.isEmpty(argument.identifier) then
        return
    end
    ---@type SceneInstance
    local sceneInstance = self._loadedScenes[argument.identifier]
    if not isNull(sceneInstance) then
        return
    end
    self.co = cs_coroutine.start(function()
        self:__TransitionCore(argument, 1, false, registerHistory) --- additive = 1
    end)
end

