---__TransitionCore
---@param argument table @ SceneArgument
---@param mode number
---@param isBack boolean
---@param registerHistory boolean
function SceneManagement:__TransitionCore(argument, mode, isBack, registerHistory)
    if string.isEmpty(argument.identifier) then
        return
    end
    if not isNull(self.preCo) then
        cs_coroutine.stop(self.preCo)
        self.preCo = nil
    end
    self.transitionId = argument.identifier
    local preArgument = self._currentSceneArgument
    self._currentSceneArgument = argument
    ---@type SceneInstance
    local preScene = self._currentScene
    if (not registerHistory) and #self._history > 0 then
        table.remove(self._history, #self._history)
    end
    cs_coroutine.yield_return(self:TransitionBefore(self._currentSceneArgument))
    ---前一场景不显示的逻辑
    if not isNull(preScene) then
        if self.onLeaveScene then
            self.onLeaveScene(preArgument)
        end
        if not isNull(preScene.Env) then
            cs_coroutine.yield_return(preScene.Env:Leave())
        end
        if self.onLeaveSceneComplete then
            self.onLeaveSceneComplete(preArgument)
        end
        preScene:Disable()
    end

    ----然后是卸载当前场景
    if mode == 1 then
        ---additive
        local function isUnloadTarget()
            local t = {}
            for i, v in pairs(self._loadedScenes) do
                if not string.isEmpty(v.identifier) and v ~= preScene and v.identifier ~= self.transitionId
                        and not self._cacheScenes:HasValue(v)
                        and not self._appendingScenes[v.identifier]
                        and not table.keyof(self._currentSceneArgument.preloadScenes, v.identifier) then
                    table.insert(t, v)
                end
            end
            return t
        end
        local unloadScenes = isUnloadTarget()
        local len = table.count(unloadScenes)

        local function sequence_coroutine(maxLen, sequence)
            if maxLen > 0 then
                local v = sequence[maxLen]
                if v then
                    cs_coroutine.yield_return(self:UnloadScene(v))
                    if v.identifier then
                        self._loadedScenes[v.identifier] = nil ---删除场景
                    end
                end
                maxLen = maxLen - 1
                cs_coroutine.yield_return(sequence_coroutine(maxLen, sequence))
            end
        end
        local maxLen = len
        cs_coroutine.yield_return(sequence_coroutine(maxLen, unloadScenes))

    end
    ---加载下一个场景,这里实际应该是一个空的小场景
    local identifier = argument.identifier
    ---@type SceneInstance
    local sceneInfo = self._loadedScenes[identifier]
    if isNull(sceneInfo) then
        ---加载场景
        cs_coroutine.yield_return(self:_LoadScene(identifier, mode))
        sceneInfo = self._loadedScenes[identifier]
        if argument.isCache then
            self._cacheScenes:EnQueue(sceneInfo)
        end
    end
    ---@type UnityEngine.SceneManagement.Scene
    local scene = sceneInfo:GetScene()
    if isNull(scene) then
        return
    end
    if isNull(sceneInfo.Env) then
        print('the identifier is null [identifier] =', identifier)
    end
    self:SetSceneActive(scene)
    if not isNull(sceneInfo.Env) then
        sceneInfo.Env:SetArgument(argument)
    end
    self._currentScene = sceneInfo
    if not isNull(self._currentScene.Env) then
        table.insert(self._history, self._currentSceneArgument)
    end
    cs_coroutine.yield_return()
    ---场景预加载的逻辑 scene prepare ---
    if not isNull(self._currentScene.Env) then
        cs_coroutine.yield_return(self._currentScene.Env:Prepare(isBack))
    end
    ---卸载前一个场景，中间存在进度过度
    if isNull(preArgument) or (not preArgument.isCache) then
        cs_coroutine.yield_return(self:UnloadScene(preScene))
    end
    cs_coroutine.yield_return(self:CleanUp())
    sceneInfo:Enable()
    ---显示当前场景
    cs_coroutine.yield_return(self:TransitionAfter(self._currentSceneArgument))
    --- scene enter的逻辑
    if self.onEnterScene then
        self.onEnterScene(self._currentSceneArgument)
    end
    if not isNull(self._currentScene.Env) then
        self._currentScene.Env:Enter(isBack)
    end
    if self.onLeaveSceneComplete then
        self.onLeaveSceneComplete(self._currentSceneArgument)
    end
    ----preload 预加载其他的场景---
    self.preCo = cs_coroutine.start(function()
        cs_coroutine.yield_return(self:_PreloadScene(argument.preloadScenes))
    end)
    self.co = nil
end

function SceneManagement:_PreloadScene(preloadScenes)
    if preloadScenes and #preloadScenes > 0 then
        local function sequence_coroutine(maxLen, sequence)
            if maxLen > 0 then
                local identifier = sequence[maxLen]
                if identifier then
                    cs_coroutine.yield_return(function ()
                        if not self._cacheScenes:HasId(identifier) then
                            cs_coroutine.yield_return(self:_LoadScene(identifier, 1))---additive
                        end
                    end)
                end
                maxLen = maxLen - 1
                cs_coroutine.yield_return(sequence_coroutine(maxLen, sequence))
            end
        end

        local length = #preloadScenes
        cs_coroutine.yield_return(sequence_coroutine(length, preloadScenes))
    end
    self.preCo = nil
end

---_LoadScene
---加载场景
---@param identifier string
---@param mode number
function SceneManagement:_LoadScene(identifier, mode)
    local co = self._loadingScenes[identifier]
    if isNull(co) then
        self._loadingScenes[identifier] = identifier
        cs_coroutine.yield_return(self:_LoadSceneCore(identifier, mode))
        self._loadingScenes[identifier] = nil
    end
end

---_LoadSceneCore
---@param identifier string
---@param mode number
function SceneManagement:_LoadSceneCore(identifier, mode)
    ---@type SceneInstance
    local sceneInstance = self._loadedScenes[identifier]
    if isNull(sceneInstance) then
        local scenePath = self._scenePaths[identifier]
        ---sceneLoaded
        ---@param s UnityEngine.SceneManagement.Scene
        ---@param m number
        local function sceneLoaded(s, m)
            if s:IsValid() then
                -- printInfo(s.name)
                sceneInstance = SceneInstance.New({ identifier, s, self:FindSceneEnv(s) })
                sceneInstance:Disable()
            end
        end
        local sceneName = scenePath.name
        local loader = ResourceModule.LoadBundleAsync(scenePath.path, nil, true)
        while not loader.IsSuccess do
            cs_coroutine.yield_return()
        end
        SceneManager.sceneLoaded('+', sceneLoaded)
        if loader.IsError then
            SceneManager.sceneLoaded('-', sceneLoaded)
            loader:Release(true)
            return
        end
        if not loader.ResultObject then
            SceneManager.sceneLoaded('-', sceneLoaded)
            loader:Release(true)
            return
        end
        local op = SceneManager.LoadSceneAsync(sceneName, CS.UnityEngine.SceneManagement.LoadSceneMode.Additive)
        if isNull(op) then
            SceneManager.sceneLoaded('-', sceneLoaded)
            loader:Release(true)
            return
        end
        while not op.isDone or not sceneInstance do
            cs_coroutine.yield_return()
        end
        sceneInstance._sceneLoader = loader
        SceneManager.sceneLoaded('-', sceneLoaded)
        if not isNull(sceneInstance:GetScene()) then
            self._loadedScenes[identifier] = sceneInstance
            cs_coroutine.yield_return(Yielders.EndOfFrame)
            ---场景加载完成的回调
        end
        if not isNull(sceneInstance.Env) then
            cs_coroutine.yield_return(sceneInstance.Env:Initialize())
        end
    else
        sceneInstance:Disable()
    end
end

---AppendScene
---添加场景
---@param identifier string
---@param activeOnLoad boolean
function SceneManagement:AppendScene(identifier, activeOnLoad)
    activeOnLoad = checkBool(activeOnLoad)
    if string.isEmpty(identifier) then
        return
    end
    return cs_coroutine.start(function ()
        ---@type SceneInstance
        local sceneInfoOld = self._loadedScenes[identifier]
        if not isNull(sceneInfoOld) then
            ---已经在加载的场景中
            if activeOnLoad then
                sceneInfoOld:Enable()
            end
            cs_coroutine.yield_return()
        else
            cs_coroutine.yield_return(self:_LoadScene(identifier, 1)) ---additive
            ---@type SceneInstance
            local sceneInfo = self._loadedScenes[identifier]
            self._appendingScenes[identifier] = sceneInfo
            if activeOnLoad then
                sceneInfo:Enable()
            end
            cs_coroutine.yield_return()
        end
    end)
end

---减少协程使用
function SceneManagement:AppendSceneAsync(identifier, activeOnLoad, callback)
    activeOnLoad = checkBool(activeOnLoad)
    if string.isEmpty(identifier) then
        return
    end

    local sceneInfoOld = self._loadedScenes[identifier]
    if not isNull(sceneInfoOld) then
        ---已经在加载的场景中
        if activeOnLoad then
            sceneInfoOld:Enable()
        end
        
        if callback ~= nil then
            callback(sceneInfoOld)
        end
    else

        self:_LoadSceneAsync(identifier, function(sceneInfo)
            if sceneInfo then
                self._appendingScenes[identifier] = sceneInfo
            
                if activeOnLoad then
                    sceneInfo:Enable()
                end
            end

            if callback ~= nil then
                callback(sceneInfo)
            end
        end )
    end
end 

function SceneManagement:_LoadSceneAsync(identifier, callback)
    ---@type SceneInstance
    local sceneInstance = self._loadedScenes[identifier]
    if isNull(sceneInstance) then
        local scenePath = self._scenePaths[identifier]
        local sceneName = scenePath.name

        self._asyncLoadingScenes[identifier] = identifier

        ResourceModule.LoadBundleAsync(scenePath.path, function(loader, ok, resultObject)
            if not self._asyncLoadingScenes[identifier] then
                ---当前场景已经不需要了
                loader:Release(true)
                return
            end

            if ok then
                cs_coroutine.start(function ()
                    local op = SceneManager.LoadSceneAsync(sceneName, CS.UnityEngine.SceneManagement.LoadSceneMode.Additive)
                    while not op.isDone do
                        cs_coroutine.yield_return()
                    end    

                    local scene = SceneManager.GetSceneByName(sceneName)

                    if not self._asyncLoadingScenes[identifier] then
                        if scene and scene:IsValid() then
                            SceneManager.UnloadSceneAsync(scene)
                        end 
                        ---当前场景已经不需要了
                        loader:Release(true)
                    else 
                        self._asyncLoadingScenes[identifier] = nil

                        if scene and scene:IsValid() then
                            local si = SceneInstance.New({ identifier, scene, self:FindSceneEnv(scene) })
                            si:Disable()
                            si._sceneLoader = loader

                            self._loadedScenes[identifier] = si

                            if not isNull(si.Env) then
                                cs_coroutine.yield_return(si.Env:Initialize())
                            end

                            ---成功callback
                            if callback then
                                callback(si)
                            end
                        else
                            ---失败callback
                            loader:Release(true)

                            if callback then
                                callback(nil)
                            end
                        end
                    end
                end)
            else
                ---失败callback
                loader:Release(true)

                if callback then
                    callback(nil)
                end
            end
        end )
    else
        sceneInstance:Disable()
    end
end

