    return self._appendingScenes[identifier]
end

---UnloadAppendedScene
---删除指定的追加的场景
---@param identifier string
function SceneManagement:UnloadAppendedSceneById(identifier)
    ---如果尚未加载完，则中断加载
    if self._asyncLoadingScenes[identifier] then
        self._asyncLoadingScenes[identifier] = nil
    end

    ---@type SceneInstance
    local sceneInstance = self._appendingScenes[identifier]
    if isNull(sceneInstance) then
        return
    end
    sceneInstance:SetIsNow(false)
    cs_coroutine.yield_return(self:UnloadAppendedScene(sceneInstance))
end

---UnloadAppendedScene
---卸载场景
---@param sceneInstance SceneInstance
function SceneManagement:UnloadAppendedScene(sceneInstance)
    if not self._appendingScenes[sceneInstance.identifier] then
        return
    end
    sceneInstance:Disable()
    self._appendingScenes[sceneInstance.identifier] = nil
    cs_coroutine.yield_return(self:UnloadScene(sceneInstance))
end

---显示末个场景
---@param identifier string
---@param active boolean
---@param isIgnore boolean 是否忽略主场景
function SceneManagement:SetActive(identifier, active, isIgnore)
    if self._loadedScenes == nil or not self._loadedScenes[identifier] then
        return
    end
    active = checkBool(active)
    for id, v in pairs(self._loadedScenes) do
        if id == identifier then
            if active then
                v:Enable()
            else
                v:Disable()
            end
        else
            if not isIgnore then
                v:Disable()
            end
        end
    end
end

---@return table<integer, SceneInstance>
function SceneManagement:GetLoadedScenes()
    return self._loadedScenes
end

---@param isDisable boolean | nil
---@return table<integer, boolean>
function SceneManagement:GetShowLoadedScenesState(isDisable)
    local showLoadedScenesState = {}
    for identifier, instance in pairs(self:GetLoadedScenes()) do
        local enable = instance:GetEnable()
        if enable then
            showLoadedScenesState[identifier] = enable
            if isDisable then
                instance:Disable()
            end
        end
    end
    return showLoadedScenesState
end

---@param scenesStateMap table<integer, boolean>
function SceneManagement:RefreshScenesState(scenesStateMap)
    for identifier, enable in pairs(scenesStateMap or {}) do
        self:SetActive(identifier, enable)
    end
end

